//! The playground island: build a query with form controls and see the SQL generated by
//! the real Memoire ORM (PostgreSQL / MySQL / SQLite) and the rows its in-memory engine
//! returns.
//!
//! The same code runs on the server, which renders the first results, and in the browser,
//! compiled to WebAssembly, where every change runs the query again locally: once the page
//! is loaded the playground needs no network at all.

use active::prelude::*;
use memoire_orm::prelude::*;

use crate::highlight::highlight;
use crate::i18n::t;
use crate::icons::{Icon, icon};
use crate::routes::Lang;
use crate::web;

#[derive(Model, Debug, Clone)]
#[memoire(table = "users")]
pub struct User {
    #[memoire(primary_key, auto_increment)]
    pub id: i64,
    #[memoire(unique)]
    pub email: String,
    pub name: String,
    pub age: Option<i32>,
}

const PEOPLE: &[(&str, &str, Option<i32>)] = &[
    ("Alice", "alice@rust.dev", Some(31)),
    ("Bob", "bob@rust.dev", Some(17)),
    ("Charlie", "charlie@rust.dev", Some(42)),
    ("Diana", "diana@rust.dev", Some(28)),
    ("Élodie", "elodie@rust.dev", Some(35)),
    ("Fernando", "fernando@rust.dev", None),
    ("Grace", "grace@rust.dev", Some(54)),
    ("Hugo", "hugo@rust.dev", Some(23)),
    ("Inès", "ines@rust.dev", Some(19)),
    ("Jules", "jules@rust.dev", Some(16)),
    ("Karim", "karim@rust.dev", Some(38)),
    ("Lucía", "lucia@rust.dev", Some(26)),
    ("Mateo", "mateo@rust.dev", Some(33)),
    ("Nora", "nora@rust.dev", None),
    ("Oliver", "oliver@rust.dev", Some(47)),
    ("Camille", "camille@rust.dev", Some(29)),
    ("Emilio", "emilio@rust.dev", Some(61)),
    ("Amelia", "amelia@rust.dev", Some(21)),
];

thread_local! {
    static DB: MemoryDb = seed();
}

fn seed() -> MemoryDb {
    let db = MemoryDb::new();
    let users: Vec<User> = PEOPLE
        .iter()
        .map(|(name, email, age)| User { id: 0, email: (*email).to_owned(), name: (*name).to_owned(), age: *age })
        .collect();
    memoire_orm::block_on(async {
        db.create_table::<User>().await?;
        User::insert_many(&db, &users).await
    })
    .expect("seeding the playground database");
    db
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum OrderField {
    Name,
    Age,
}

/// What the visitor picked in the controls.
#[derive(Clone, PartialEq, Debug)]
pub struct Params {
    /// `User::AGE.ge(min_age)`
    pub min_age: i32,
    /// `User::NAME.contains(name_contains)`; empty = no name filter.
    pub name_contains: String,
    pub order_by: OrderField,
    pub descending: bool,
    pub limit: u32,
}

impl Default for Params {
    fn default() -> Self {
        Params {
            min_age: 18,
            name_contains: "li".to_string(),
            order_by: OrderField::Name,
            descending: false,
            limit: 20,
        }
    }
}

/// One row of the result: `(id, name, email, age)`.
pub type Row = (i64, String, String, Option<i32>);

/// What one run of the query gives.
#[derive(Clone, PartialEq, Debug, Default)]
pub struct Output {
    pub sql_postgres: String,
    pub sql_mysql: String,
    pub sql_sqlite: String,
    pub rows: Vec<Row>,
    /// Execution time of the query, in microseconds.
    pub micros: f64,
    /// Run by the server (first render) rather than in the browser.
    pub on_server: bool,
}

fn build(params: &Params) -> memoire_orm::Select<User> {
    let mut filter = User::AGE.ge(params.min_age);
    let needle = params.name_contains.trim();
    if !needle.is_empty() {
        filter = filter & User::NAME.contains(needle);
    }
    let order = match (params.order_by, params.descending) {
        (OrderField::Name, false) => User::NAME.asc(),
        (OrderField::Name, true) => User::NAME.desc(),
        (OrderField::Age, false) => User::AGE.asc(),
        (OrderField::Age, true) => User::AGE.desc(),
    };
    User::query().filter(filter).order_by(order).limit(u64::from(params.limit))
}

/// Builds the query, renders it for every dialect and runs it on the in-memory engine.
/// The time reported is the average of many runs: browsers only expose coarse timers.
pub fn run(params: &Params) -> Output {
    let query = build(params);
    let (sql_postgres, sql_mysql, sql_sqlite) =
        (query.to_sql(Dialect::Postgres), query.to_sql(Dialect::MySql), query.to_sql(Dialect::Sqlite));
    DB.with(|db| {
        const RUNS: u32 = 200;
        let start = web::now_ms();
        let mut users = Vec::new();
        for _ in 0..RUNS {
            users = memoire_orm::block_on(query.clone().all(db)).unwrap_or_default();
        }
        let micros = (web::now_ms() - start) * 1000.0 / f64::from(RUNS);
        Output {
            sql_postgres,
            sql_mysql,
            sql_sqlite,
            rows: users.into_iter().map(|u| (u.id, u.name, u.email, u.age)).collect(),
            micros,
            on_server: !cfg!(target_arch = "wasm32"),
        }
    })
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
enum Flavor {
    Postgres,
    MySql,
    Sqlite,
}

impl Flavor {
    const ALL: [Flavor; 3] = [Flavor::Postgres, Flavor::MySql, Flavor::Sqlite];

    fn label(self) -> &'static str {
        match self {
            Flavor::Postgres => "PostgreSQL",
            Flavor::MySql => "MySQL",
            Flavor::Sqlite => "SQLite",
        }
    }

    fn placeholder(self, n: usize) -> String {
        match self {
            Flavor::Postgres => format!("${n}"),
            Flavor::MySql | Flavor::Sqlite => "?".to_string(),
        }
    }

    fn of(self, out: &Output) -> &str {
        match self {
            Flavor::Postgres => &out.sql_postgres,
            Flavor::MySql => &out.sql_mysql,
            Flavor::Sqlite => &out.sql_sqlite,
        }
    }
}

/// The Rust code equivalent to the current controls.
pub fn rust_code(p: &Params) -> String {
    let filter = if p.name_contains.is_empty() {
        format!("User::AGE.ge({})", p.min_age)
    } else {
        format!("User::AGE.ge({}) & User::NAME.contains({:?})", p.min_age, p.name_contains)
    };
    let col = match p.order_by {
        OrderField::Name => "NAME",
        OrderField::Age => "AGE",
    };
    let dir = if p.descending { "desc" } else { "asc" };
    format!(
        "let users = User::query()\n    .filter({filter})\n    .order_by(User::{col}.{dir}())\n    .limit({})\n    .all(&db)\n    .await?;",
        p.limit
    )
}

/// Bound parameter values, in order.
fn bound_params(p: &Params) -> Vec<String> {
    let mut v = vec![p.min_age.to_string()];
    if !p.name_contains.is_empty() {
        v.push(format!("'%{}%'", memoire_orm::escape_like(p.name_contains.trim())));
    }
    v
}

pub fn fmt_micros(us: f64) -> String {
    if us < 0.01 {
        "< 0.01 µs".to_string()
    } else if us < 1000.0 {
        format!("{us:.2} µs")
    } else {
        format!("{:.2} ms", us / 1000.0)
    }
}

/// The island (`props`: the language code).
pub fn playground(props: &str) -> Node {
    let lang = Lang::parse(props.split(':').next().unwrap_or_default()).unwrap_or(Lang::En);
    let tx = t(lang);
    let params = use_state(Params::default());
    let out = use_state(run(&Params::default()));
    let dialect = use_state(Flavor::Postgres);
    let copied = use_state(false);

    // Every change runs the query again (in the browser: WebAssembly, no network).
    let change = move |f: &dyn Fn(&mut Params) -> bool| {
        let mut next = params.get();
        if f(&mut next) && next != params.get() {
            out.set(run(&next));
            params.set(next);
        }
    };

    let age = label()
        .class("field")
        .child(
            span()
                .class("field-label")
                .text(tx.pg_min_age)
                .child(output().class("field-value").text_dyn(move || params.with(|p| p.min_age.to_string()))),
        )
        .child(
            input()
                .attr("type", "range")
                .attr("min", "0")
                .attr("max", "100")
                .attr_dyn("value", move || params.with(|p| p.min_age.to_string()))
                .attr_dyn("style", move || params.with(|p| format!("--pct:{}%", p.min_age)))
                .on_input(move |e| {
                    let value = e.value();
                    change(&|p| value.parse().map(|v: i32| p.min_age = v.clamp(0, 100)).is_ok());
                }),
        );

    let name = label().class("field").child(span().class("field-label").text(tx.pg_name_contains)).child(
        input()
            .attr("type", "text")
            .class("input")
            .attr("placeholder", tx.pg_name_placeholder)
            .attr("spellcheck", "false")
            .attr("autocomplete", "off")
            .attr_dyn("value", move || params.with(|p| p.name_contains.clone()))
            .on_input(move |e| {
                let value: String = e.value().chars().take(32).collect();
                change(&|p| {
                    p.name_contains = value.clone();
                    true
                });
            }),
    );

    let order = label().class("field").child(span().class("field-label").text(tx.pg_order_by)).child(
        select()
            .class("input")
            .attr_dyn("value", move || {
                params.with(|p| if p.order_by == OrderField::Age { "age" } else { "name" }.to_string())
            })
            .on("change", move |e| {
                let age = e.value() == "age";
                change(&|p| {
                    p.order_by = if age { OrderField::Age } else { OrderField::Name };
                    true
                });
            })
            .child(
                option()
                    .attr("value", "name")
                    .bool_attr("selected", move || params.with(|p| p.order_by == OrderField::Name))
                    .text(tx.pg_order_name),
            )
            .child(
                option()
                    .attr("value", "age")
                    .bool_attr("selected", move || params.with(|p| p.order_by == OrderField::Age))
                    .text(tx.pg_order_age),
            ),
    );

    let direction = div().class("field").child(span().class("field-label").text(tx.pg_direction)).child(
        button()
            .attr("type", "button")
            .class("dir-toggle")
            .class_if("is-desc", move || params.with(|p| p.descending))
            .attr_dyn("aria-pressed", move || params.with(|p| p.descending.to_string()))
            .on_click(move |_| {
                change(&|p| {
                    p.descending = !p.descending;
                    true
                })
            })
            .child(span().class("dir-arrow").child(icon(Icon::ArrowUp)))
            .text_dyn(move || if params.with(|p| p.descending) { tx.pg_desc } else { tx.pg_asc }.to_string()),
    );

    let limit = label().class("field").child(span().class("field-label").text(tx.pg_limit)).child(
        input()
            .attr("type", "number")
            .class("input")
            .attr("min", "1")
            .attr("max", "100")
            .attr_dyn("value", move || params.with(|p| p.limit.to_string()))
            .on_input(move |e| {
                let value = e.value();
                // An empty or partial field keeps the previous limit (and lets you type).
                change(&|p| value.parse().map(|v: u32| p.limit = v.clamp(1, 100)).is_ok());
            }),
    );

    let controls = aside()
        .class("pg-controls glass")
        .child(
            div().class("pg-head").child(h2().text(tx.pg_controls)).child(
                button()
                    .attr("type", "button")
                    .class("btn btn-ghost btn-xs")
                    .on_click(move |_| {
                        change(&|p| {
                            *p = Params::default();
                            true
                        })
                    })
                    .text(tx.pg_reset),
            ),
        )
        .child(age)
        .child(name)
        .child(div().class("field-row").child(order).child(direction))
        .child(limit)
        .child(
            div()
                .class("pg-rust")
                .child(span().class("pane-title").text(tx.pg_rust))
                .child(pre().child(code().html_dyn(move || params.with(|p| highlight(&rust_code(p), "rust"))))),
        );

    let sql_pane = div()
        .class("pg-pane glass")
        .child(
            div()
                .class("pane-head")
                .child(span().class("pane-title").text(tx.pg_sql))
                .child(div().class("dialect-tabs").attr("role", "tablist").children(Flavor::ALL.map(|d| {
                    button()
                        .attr("type", "button")
                        .attr("role", "tab")
                        .class("dialect-tab")
                        .class_if("active", move || dialect.get() == d)
                        .attr_dyn("aria-selected", move || (dialect.get() == d).to_string())
                        .on_click(move |_| dialect.set(d))
                        .text(d.label())
                })))
                .child(
                    button()
                        .attr("type", "button")
                        .class("cw-copy")
                        .class_if("is-copied", move || copied.get())
                        .attr("aria-label", tx.copy)
                        .on_click(move |_| {
                            web::copy_text(&out.with(|o| dialect.get().of(o).to_string()));
                            copied.set(true);
                            web::after(1500, move || copied.set(false));
                        })
                        .children_dyn(move || vec![icon(if copied.get() { Icon::Check } else { Icon::Copy }).into()]),
                ),
        )
        // Rebuilt on every change, so that its entrance animation plays again.
        .children_dyn(move || {
            let html = out.with(|o| highlight(dialect.get().of(o), "sql"));
            vec![pre().class("pg-sql wrap").child(code().html(html)).into()]
        })
        .child(div().class("pg-params").child(span().class("pane-subtitle").text(tx.pg_params)).children_dyn(
            move || {
                let d = dialect.get();
                params
                    .with(bound_params)
                    .into_iter()
                    .enumerate()
                    .map(|(i, v)| {
                        span()
                            .class("param-chip")
                            .child(code().text(d.placeholder(i + 1)))
                            .text(" = ")
                            .child(code().text(v))
                            .into()
                    })
                    .collect()
            },
        ));

    let result_pane = div()
        .class("pg-pane glass")
        .child(
            div()
                .class("pane-head")
                .child(span().class("pane-title").text(tx.pg_result))
                .child(
                    span()
                        .class("row-count")
                        .text_dyn(move || format!("{} {}", out.with(|o| o.rows.len()), tx.pg_rows)),
                )
                .children_dyn(move || {
                    let (micros, on_server) = out.with(|o| (o.micros, o.on_server));
                    let place = if on_server { tx.pg_on_server } else { "WebAssembly" };
                    vec![
                        span()
                            .class("exec-badge")
                            .child(icon(Icon::Zap))
                            .text(format!("{} {} · {place}", tx.pg_exec, fmt_micros(micros)))
                            .into(),
                    ]
                }),
        )
        .child(p().class("pg-empty").bool_attr("hidden", move || out.with(|o| !o.rows.is_empty())).text(tx.pg_no_rows))
        .child(
            div().class("table-wrap").bool_attr("hidden", move || out.with(|o| o.rows.is_empty())).child(
                table()
                    .class("pg-table")
                    .child(thead().child(tr().children(["id", "name", "email", "age"].map(|h| th().text(h)))))
                    .child(tbody().children_keyed(
                        move || out.with(|o| o.rows.iter().cloned().enumerate().collect::<Vec<_>>()),
                        |(_, row)| row.0,
                        |(i, (id, name, email, age))| {
                            tr().style(format!("--i:{i}"))
                                .child(td().class("num").text(id.to_string()))
                                .child(td().text(name.clone()))
                                .child(td().class("muted").text(email.clone()))
                                .child(
                                    td().class("num").text(age.map_or_else(|| "NULL".to_string(), |a| a.to_string())),
                                )
                                .into()
                        },
                    )),
            ),
        );

    section()
        .class("container playground hero-anim")
        .style("--d:240ms")
        .child(controls)
        .child(
            div()
                .class("pg-output")
                .child(sql_pane)
                .child(result_pane)
                .child(p().class("pg-note").child(icon(Icon::Cpu)).child(span().text(tx.pg_offline_note))),
        )
        .into()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn runs_the_real_orm() {
        let out = run(&Params::default());
        // Names containing "li", 18 or older.
        let names: Vec<&str> = out.rows.iter().map(|r| r.1.as_str()).collect();
        assert!(names.contains(&"Alice") && names.contains(&"Charlie"), "{names:?}");
        assert!(out.rows.iter().all(|r| r.3.unwrap_or(0) >= 18));
        assert!(out.sql_postgres.contains("$1") && out.sql_mysql.contains('?'));
        assert!(out.on_server);
        let none = run(&Params { min_age: 100, ..Params::default() });
        assert!(none.rows.is_empty());
    }

    #[test]
    fn renders_on_the_server_with_results() {
        let html = active::island("playground", "fr", playground).render();
        assert!(html.contains("Constructeur de requête"));
        assert!(html.contains("<td>Alice</td>"), "{html}");
        assert!(html.contains("pg-sql"));
        assert!(html.contains("serveur"));
    }
}
